mapper.select:
/* Attd12Mapper.selectSharedDeviceLoginSuspects */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
/* 스코프(사업장/부서) 내 대상 사용자 + 부서명 */ target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL ),
/* 스코프 내 APP 로그인 이력(판정/표시 모수). login_hist 를 target_user 로 제한 */ scoped_app_login AS ( SELECT H.DEVICE_UUID , H.USER_CD , H.LOGIN_DTIME , H.CLIENT_TYPE , H.DEVICE_MODEL , H.OS_VERSION FROM TB_USER_DEVICE_LOGIN_HIST H INNER JOIN target_user TU ON H.CMPNY_CD = TU.CMPNY_CD AND H.USER_CD = TU.USER_CD WHERE H.CMPNY_CD = #{gvCmpnyCd} AND H.CLIENT_TYPE = 'APP' AND H.DEVICE_UUID IS NOT NULL ),
/* 공유 의심 기기: 조회월 APP 로그인(후보 L) 중, 같은 기기를 직전 7일 내에 다른 USER_CD 가 APP 로그인(L2)한 적이 있는 기기의 distinct DEVICE_UUID. 후보·상대 모두 스코프 내 사용자(scoped_app_login)로 제한. */ suspect_device AS ( SELECT DISTINCT L.DEVICE_UUID FROM scoped_app_login L WHERE DATE_FORMAT(L.LOGIN_DTIME, '%Y%m') = REPLACE(#{workYm}, '-', '') AND EXISTS ( SELECT 1 FROM scoped_app_login L2 WHERE L2.DEVICE_UUID = L.DEVICE_UUID AND L2.USER_CD <> L.USER_CD AND L2.LOGIN_DTIME >= L.LOGIN_DTIME - INTERVAL 7 DAY AND L2.LOGIN_DTIME < L.LOGIN_DTIME ) )
/* 의심 기기에 관여한 스코프 내 APP 로그인 이력 전체(기기 중심 표시 모수). 조회월 후보 로그인의 직전 7일 윈도우에 들어오는 로그인까지 함께 노출하기 위해 조회월 시작 7일 전부터의 로그인을 포함한다. */ SELECT H.DEVICE_UUID AS deviceUuid , TU.USER_CD AS userCd , TU.USER_ID AS userId , TU.USER_NM AS userNm , TU.NODE_NM AS nodeNm , S.SITE_NM AS siteNm , DATE_FORMAT(H.LOGIN_DTIME, '%Y%m%d%H%i%s') AS loginDtime , H.CLIENT_TYPE AS clientType , H.DEVICE_MODEL AS deviceModel , H.OS_VERSION AS osVersion FROM TB_USER_DEVICE_LOGIN_HIST H INNER JOIN suspect_device SD ON SD.DEVICE_UUID = H.DEVICE_UUID INNER JOIN target_user TU ON TU.CMPNY_CD = H.CMPNY_CD AND TU.USER_CD = H.USER_CD INNER JOIN TB_SITE S ON S.CMPNY_CD = TU.CMPNY_CD AND S.SITE_CD = TU.SITE_CD WHERE H.CMPNY_CD = #{gvCmpnyCd} AND H.CLIENT_TYPE = 'APP' AND H.DEVICE_UUID IS NOT NULL AND H.LOGIN_DTIME >= DATE_SUB(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d'), INTERVAL 7 DAY) AND H.LOGIN_DTIME < DATE_ADD(STR_TO_DATE(CONCAT(REPLACE(#{workYm}, '-', ''), '01'), '%Y%m%d'), INTERVAL 1 MONTH) ORDER BY H.DEVICE_UUID, H.LOGIN_DTIME, TU.USER_CD
